import * as THREE from './vendor/three.module.js';
export let HEROES=[],ACCESSORIES=[];
export function configureHeroes(catalog){HEROES=catalog.heroes;ACCESSORIES=catalog.accessories}
export function validateOperative(value={}){if(!value||typeof value!=='object')value={};return {hero:HEROES.some(h=>h.id===value.hero)?value.hero:HEROES[0]?.id,head:ACCESSORIES.some(a=>a.id===value.head&&a.slot==='head')?value.head:'none',back:ACCESSORIES.some(a=>a.id===value.back&&a.slot==='back')?value.back:'none'}}
export function loadOperative(){try{return validateOperative(JSON.parse(localStorage.getItem('fusionfall-operative')||'{}'))}catch{return validateOperative()}}
export function saveOperative(value){try{localStorage.setItem('fusionfall-operative',JSON.stringify(value))}catch{}}
export function createHeroActor(assets,selection){
 const config=validateOperative(selection),hero=HEROES.find(h=>h.id===config.hero),root=new THREE.Group(),body=assets.model(hero.asset,{height:1.8,uniqueMaterials:true});root.name=hero.name;root.add(body);const controller=body.userData.animation,bones=controller?.bones||[],sockets={};for(const [key,name]of Object.entries(hero.sockets))sockets[key]=bones.find(b=>b.name===name);
 const gear=[],clip=new THREE.Plane(new THREE.Vector3(0,-1,0),1.1),materials=[],armBones=new Set();
 bones.forEach((bone,index)=>{for(let b=bone;b&&b!==body;b=b.parent)if(b===sockets.leftUpperArm||b===sockets.rightUpperArm){armBones.add(index);break}});
 body.traverse(o=>{if(o.isMesh){const mask=new Float32Array(o.geometry.attributes.position.count),indices=o.geometry.attributes.skinIndex,weights=o.geometry.attributes.skinWeight;if(indices&&weights)for(let v=0;v<mask.length;v++)for(let k=0;k<4;k++)if(armBones.has(indices.array[v*4+k]))mask[v]+=weights.array[v*4+k];o.geometry.setAttribute('fpArmMask',new THREE.Float32BufferAttribute(mask,1));materials.push(...(Array.isArray(o.material)?o.material:[o.material]));o.castShadow=true}});
 for(const mat of materials){const hideArms={value:0};mat.userData.hideAvatarArms=hideArms;mat.onBeforeCompile=shader=>{shader.uniforms.hideAvatarArms=hideArms;shader.vertexShader=shader.vertexShader.replace('#include <common>','#include <common>\nattribute float fpArmMask; varying float vFpArmMask;').replace('#include <begin_vertex>','#include <begin_vertex>\nvFpArmMask=fpArmMask;');shader.fragmentShader=shader.fragmentShader.replace('#include <common>','#include <common>\nuniform float hideAvatarArms; varying float vFpArmMask;').replace('#include <clipping_planes_fragment>','#include <clipping_planes_fragment>\nif(hideAvatarArms>.5 && vFpArmMask>.2) discard;')};mat.customProgramCacheKey=()=>'operative-fp-arm-mask-v1'}
 for(const slot of ['head','back']){const record=ACCESSORIES.find(a=>a.id===config[slot]);if(!record)continue;const object=assets.model(record.asset,{height:record.targetHeight});root.add(object);object.rotation.set(...record.rotation);root.updateMatrixWorld(true);const socket=sockets[slot],base=socket?socket.getWorldQuaternion(new THREE.Quaternion()):new THREE.Quaternion();gear.push({slot,record,object,base});object.traverse(o=>{if(o.isMesh)o.castShadow=true})}
 root.updateMatrixWorld(true);const restingFeet=[sockets.leftFoot,sockets.rightFoot].filter(Boolean).map(b=>root.worldToLocal(b.getWorldPosition(new THREE.Vector3())).y),restingFootY=restingFeet.length?Math.min(...restingFeet):.1;
 const previous=new Map(),axis=new THREE.Vector3(),q=new THREE.Quaternion(),parentQ=new THREE.Quaternion();
 function restore(){for(const [bone,state]of previous){bone.position.copy(state.position);bone.quaternion.copy(state.quaternion)}previous.clear()}
 function remember(bone){if(bone&&!previous.has(bone))previous.set(bone,{position:bone.position.clone(),quaternion:bone.quaternion.clone()})}
 function rotate(key,angle){const bone=sockets[key];if(!bone||!angle)return;remember(bone);root.updateMatrixWorld(true);axis.set(1,0,0).applyQuaternion(root.quaternion);bone.parent.getWorldQuaternion(parentQ);axis.applyQuaternion(parentQ.invert()).normalize();q.setFromAxisAngle(axis,angle);bone.quaternion.premultiply(q)}
 function offset(key,dy){const bone=sockets[key];if(!bone||!dy)return;remember(bone);root.updateMatrixWorld(true);const delta=new THREE.Vector3(0,dy,0);bone.parent.getWorldQuaternion(parentQ);delta.applyQuaternion(parentQ.invert());const scale=new THREE.Vector3();bone.parent.getWorldScale(scale);delta.divide(scale);bone.position.add(delta)}
 function update(dt,{moving=false,sprinting=false,crouch=0,slide=0,firing=false,melee=0,firstPerson=false,eyeHeight=1.68}={}){
  restore();body.position.set(0,0,0);controller?.update(dt*(sprinting?1.25:crouch>.3?.7:1),moving&&slide<.3?(crouch>.3?'walk':'run'):firing?'ready':'idle');
  const bend=crouch*.8+slide*1.35;offset('pelvis',-crouch*.28-slide*.48);rotate('leftThigh',-bend);rotate('rightThigh',-bend+(slide?-.12:0));rotate('leftCalf',crouch*1.5+slide*.35);rotate('rightCalf',crouch*1.5+slide*.5);rotate('back',crouch*.2-slide*.25);
  if(firing){rotate('rightUpperArm',-.48);rotate('rightForearm',-.45)}if(melee>0){rotate('rightUpperArm',-melee*1.2);rotate('rightForearm',melee*.85);rotate('back',-melee*.15)}
  root.updateMatrixWorld(true);if(crouch>.05||slide>.05){const feet=[sockets.leftFoot,sockets.rightFoot].filter(Boolean).map(b=>root.worldToLocal(b.getWorldPosition(new THREE.Vector3())).y);if(feet.length)body.position.y=Math.max(-.4,restingFootY-Math.min(...feet));}
  root.updateMatrixWorld(true);
  for(const item of gear){const bone=sockets[item.slot];if(bone){root.worldToLocal(bone.getWorldPosition(item.object.position));const inverseRoot=root.getWorldQuaternion(new THREE.Quaternion()).invert(),relative=bone.getWorldQuaternion(new THREE.Quaternion()).premultiply(inverseRoot).multiply(item.base.clone().invert()),offset=item.slot==='head'?new THREE.Vector3(...hero.attachmentFit.headOffset).add(new THREE.Vector3(0,-.08,0)):new THREE.Vector3(0,-item.record.targetHeight*.5,-.16);item.object.position.add(offset.applyQuaternion(relative));item.object.quaternion.copy(relative).multiply(new THREE.Quaternion().setFromEuler(new THREE.Euler(...item.record.rotation)));}else item.object.position.set(0,item.slot==='head'?1.75:1.05,item.slot==='back'?-.16:0);item.object.visible=!firstPerson;}
  root.getWorldPosition(axis);clip.constant=axis.y+eyeHeight*.65;for(const mat of materials){mat.clippingPlanes=firstPerson?[clip]:null;mat.userData.hideAvatarArms.value=firstPerson?1:0}
 }
 function dispose(){restore();controller?.dispose();materials.forEach(m=>m.dispose());root.parent?.remove(root)}
 return {root,body,hero,config,gear,sockets,update,dispose};
}
